 refreshProject:reloadProject,quality:checkQuality,exportProject,inferProject,pipeline:openPipeline,editLabels,distributeAssets,
 filterSplit:async e=>{S.split=e.dataset.value;S.page=1;await listAssets();projectPage()},
 prevPage:async()=>{S.page=Math.max(1,S.page-1);await listAssets();projectPage();installDatasetTools();history.replaceState({view:'project',wid:S.wid,pid:S.project.id,page:S.page},'',`#project-${S.project.id}-page-${S.page}`);window.scrollTo({top:0,behavior:'smooth'})},
 nextPage:async()=>{if(S.page*48>=S.total)return;S.page+=1;await listAssets();projectPage();installDatasetTools();history.replaceState({view:'project',wid:S.wid,pid:S.project.id,page:S.page},'',`#project-${S.project.id}-page-${S.page}`);window.scrollTo({top:0,behavior:'smooth'})},
 openAsset:async e=>openAsset(Number(e.dataset.id)),deleteProject,deleteWorkspace,removeMember,
 backProject:async()=>{if(!promptDirty())return;history.back()},
 previousAsset:()=>navigateAsset(-1),nextAsset:()=>navigateAsset(1),
 modeSelect:()=>{S.editMode='select';renderEditor()},modeDraw:()=>{S.editMode='draw';renderEditor()},
