document.addEventListener('click',e=>{if(e.target.matches('.overlay')){modal.innerHTML='';return}const target=e.target.closest('[data-action]');if(!target||target.disabled)return;const h=handlers[target.dataset.action];if(h)secureAction(h)(target)});
document.addEventListener('change',e=>{if(e.target.id==='workspace-picker')secureAction(async()=>{if(S.view==='editor'&&!promptDirty())return;if(S.editor)await releaseEditor();S.wid=Number(e.target.value);S.project=null;await loadWorkspace()})();if(e.target.id==='review-filter')secureAction(async()=>{S.state=e.target.value;S.page=1;await listAssets();projectPage();installDatasetTools()})();if(e.target.id==='annotator-filter')secureAction(async()=>{S.annotatedBy=Number(e.target.value);S.page=1;await listAssets();projectPage();installDatasetTools()})();if(e.target.id==='assignee-filter')secureAction(async()=>{S.assignedTo=Number(e.target.value);S.page=1;await listAssets();projectPage();installDatasetTools()})();if(e.target.id==='review-state'&&S.editor){S.editor.state=e.target.value;S.dirty=true;refreshInspector()}});
let timer;
document.addEventListener('input',e=>{if(e.target.id==='project-search'){clearTimeout(timer);const value=e.target.value;timer=setTimeout(()=>secureAction(async()=>{S.query=value;S.page=1;await listAssets();projectPage();el('project-search')?.focus();el('project-search')?.setSelectionRange(value.length,value.length)})(),320)}
 if(e.target.id==='rail-search'){S.railQuery=e.target.value;const rail=el('rail-content');if(rail)rail.innerHTML=railItems(S.assets.filter(a=>a.image_rel.toLowerCase().includes(S.railQuery.toLowerCase())))}});
document.addEventListener('submit',e=>{if(e.target.id!=='login-form')return;e.preventDefault();secureAction(async()=>{const f=new FormData(e.target);const d=await send('POST','/auth/login',{username:f.get('username'),password:f.get('password')});S.user=d.user;S.csrf=d.csrf;await fetchWorkspaces();await loadWorkspace()})()});
document.addEventListener('keydown',e=>{if(S.view!=='editor')return;const typing=/^(INPUT|TEXTAREA|SELECT)$/.test(document.activeElement?.tagName||'')||document.activeElement?.isContentEditable;if(typing)return;
 const cmd=e.ctrlKey||e.metaKey;if(cmd&&e.key.toLowerCase()==='s'){e.preventDefault();secureAction(()=>saveImage(false))();return}if(cmd&&e.key.toLowerCase()==='z'){e.preventDefault();undoRedo('undo');return}if(cmd&&e.key.toLowerCase()==='y'){e.preventDefault();undoRedo('redo');return}if(e.key==='ArrowLeft'){e.preventDefault();secureAction(()=>navigateAsset(-1))();return}if(e.key==='ArrowRight'){e.preventDefault();secureAction(()=>navigateAsset(1))();return}if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();deleteBox()}if(e.key.toLowerCase()==='v'&&!cmd){S.editMode='select';renderEditor()}if(e.key.toLowerCase()==='b'&&!cmd){S.editMode='draw';renderEditor()}});
window.addEventListener('popstate',e=>secureAction(async()=>{const state=e.state||{view:'home',wid:S.wid};if(S.view==='editor'&&!promptDirty()){history.forward();return}if(S.editor)await releaseEditor();if(state.wid&&state.wid!==S.wid){S.wid=state.wid;S.projects=await api(`/workspaces/${S.wid}/projects`)}if(state.view==='editor'&&state.pid&&state.aid){await openProject(state.pid,false);S.page=state.page||1;await listAssets();await openAsset(state.aid,false)}else if(state.view==='project'&&state.pid){await openProject(state.pid,false);S.page=state.page||1;if(S.page!==1)await reloadProject()}else{S.project=null;dashboard()}})());
window.addEventListener('beforeunload',e=>{if(S.dirty){e.preventDefault();e.returnValue=''}});
async function boot(){try{const d=await api('/auth/me');S.user=d.user;S.csrf=d.csrf;await fetchWorkspaces();await loadWorkspace();history.replaceState({view:'home',wid:S.wid},'','#overview')}catch{renderLogin()}}
boot();
